DROP TABLE IF EXISTS `accounting_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `accounting_entries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `operation_id` bigint(20) unsigned NOT NULL,
  `entry_type` enum('glider_flight','tow_charge','towplane_own','maintenance','manual') NOT NULL,
  `callsign` varchar(32) DEFAULT NULL,
  `pilot_name` varchar(128) DEFAULT NULL,
  `attendant_name` varchar(128) DEFAULT NULL,
  `departure_time` datetime DEFAULT NULL,
  `departure_location` varchar(16) DEFAULT NULL,
  `arrival_time` datetime DEFAULT NULL,
  `arrival_location` varchar(16) DEFAULT NULL,
  `flight_minutes` int(11) DEFAULT NULL,
  `landing_count` int(11) NOT NULL DEFAULT 1,
  `start_type` tinyint(4) DEFAULT NULL,
  `charge_mode` tinyint(4) NOT NULL DEFAULT 2,
  `invoiced` tinyint(4) NOT NULL DEFAULT 0,
  `comment` text DEFAULT NULL,
  `tow_height_m` int(11) DEFAULT NULL,
  `tow_minutes` int(11) DEFAULT NULL,
  `tow_callsign` varchar(32) DEFAULT NULL,
  `tow_pilot_name` varchar(128) DEFAULT NULL,
  `tow_arrival_location` varchar(16) DEFAULT NULL,
  `vf_flight_type_id` int(11) DEFAULT NULL,
  `km` int(11) DEFAULT NULL,
  `plane_wkz` varchar(50) DEFAULT NULL,
  `plane_designation` varchar(128) DEFAULT NULL,
  `cost_center` varchar(64) DEFAULT NULL,
  `approval_role` enum('glider_pilot','tow_pilot','dispatcher') NOT NULL,
  `approval_status` enum('pending','correction_required','approved','exported') NOT NULL DEFAULT 'pending',
  `approved_by` varchar(128) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `correction_note` text DEFAULT NULL,
  `exported_at` datetime DEFAULT NULL,
  `export_batch` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_entries_status` (`approval_status`,`exported_at`),
  KEY `idx_entries_date` (`departure_time`),
  KEY `idx_entries_operation` (`operation_id`),
  KEY `idx_accounting_approval_status` (`approval_status`),
  CONSTRAINT `accounting_entries_ibfk_1` FOREIGN KEY (`operation_id`) REFERENCES `operations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=220 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
