--
-- Table structure for table `raw_flights`
--

DROP TABLE IF EXISTS `raw_flights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `raw_flights` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source` varchar(50) NOT NULL DEFAULT 'ktrax',
  `source_uid` varchar(128) DEFAULT NULL,
  `flight_date` date NOT NULL,
  `aircraft_callsign` varchar(32) NOT NULL,
  `aircraft_type` int(11) DEFAULT NULL,
  `takeoff_time` time DEFAULT NULL,
  `takeoff_airfield` varchar(16) DEFAULT NULL,
  `landing_time` time DEFAULT NULL,
  `landing_airfield` varchar(16) DEFAULT NULL,
  `duration_text` varchar(16) DEFAULT NULL,
  `tow_id` varchar(128) DEFAULT NULL,
  `tow_callsign` varchar(32) DEFAULT NULL,
  `tow_height_m` int(11) DEFAULT NULL,
  `raw_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`raw_json`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_raw_source` (`source`,`source_uid`),
  KEY `idx_raw_date_aircraft` (`flight_date`,`aircraft_callsign`)
) ENGINE=InnoDB AUTO_INCREMENT=304 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

