--
-- Table structure for table `tow_segments`
--

DROP TABLE IF EXISTS `tow_segments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `tow_segments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `operation_id` bigint(20) unsigned NOT NULL,
  `glider_raw_flight_id` bigint(20) unsigned DEFAULT NULL,
  `tow_raw_flight_id` bigint(20) unsigned DEFAULT NULL,
  `glider_callsign` varchar(32) NOT NULL,
  `tow_callsign` varchar(32) NOT NULL,
  `tow_pilot_name` varchar(128) DEFAULT NULL,
  `segment_start` datetime DEFAULT NULL,
  `segment_end` datetime DEFAULT NULL,
  `tow_minutes` int(11) DEFAULT NULL,
  `tow_height_m` int(11) DEFAULT NULL,
  `cost_center` varchar(64) DEFAULT NULL,
  `approval_status` enum('pending','correction_required','approved','exported') NOT NULL DEFAULT 'pending',
  `approved_by` varchar(128) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `correction_note` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tow_segment_operation` (`operation_id`),
  KEY `idx_tow_segments_date` (`segment_start`),
  KEY `idx_tow_segments_towplane` (`tow_callsign`),
  KEY `idx_tow_segments_status` (`approval_status`),
  KEY `fk_tow_segments_glider_raw` (`glider_raw_flight_id`),
  KEY `fk_tow_segments_tow_raw` (`tow_raw_flight_id`),
